create extension if not exists pgcrypto;
create type public.product_status as enum ('NEW','RESEARCHING','RESEARCHED','NEEDS_REVIEW','READY','APPROVED','PUBLISHING','PUBLISHED','ERROR','CONFLICT','LOW_CONFIDENCE','NO_DATA');
create type public.confidence_level as enum ('HIGH','MEDIUM','LOW');
create type public.user_role as enum ('ADMIN','MANAGER','VIEWER');
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,role public.user_role not null default 'VIEWER',created_at timestamptz not null default now());
create table if not exists public.stores(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,created_at timestamptz not null default now());
create table if not exists public.store_memberships(id uuid primary key default gen_random_uuid(),store_id uuid not null references public.stores(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,role public.user_role not null default 'VIEWER',created_at timestamptz not null default now(),unique(store_id,user_id));
create table if not exists public.products(id uuid primary key default gen_random_uuid(),store_id uuid not null references public.stores(id) on delete cascade,ozon_product_id text,seller_article text not null,name text,brand text,category text,status public.product_status not null default 'NEW',confidence_score integer check(confidence_score between 0 and 100),raw_ozon jsonb not null default '{}'::jsonb,last_researched_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(store_id,seller_article));
create index if not exists products_store_status_idx on public.products(store_id,status);create index if not exists products_article_idx on public.products(store_id,lower(seller_article));
create table if not exists public.product_drafts(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,title text,description text,hashtags jsonb not null default '[]'::jsonb,attributes jsonb not null default '{}'::jsonb,product_type text,tnved text,oem_numbers jsonb not null default '[]'::jsonb,cross_references jsonb not null default '[]'::jsonb,applicability jsonb not null default '[]'::jsonb,warnings jsonb not null default '[]'::jsonb,conflicts jsonb not null default '[]'::jsonb,confidence_score integer check(confidence_score between 0 and 100),status text not null default 'DRAFT',created_by uuid references public.profiles(id),approved_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.part_numbers(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,number text not null,number_type text not null,source_id uuid,confirmed boolean not null default false,notes text,created_at timestamptz not null default now());
create index if not exists part_numbers_product_idx on public.part_numbers(product_id);create index if not exists part_numbers_number_idx on public.part_numbers(lower(number));
create table if not exists public.vehicle_applications(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,brand text not null,model text not null,generation text,body text,year_from integer,year_to integer,engine text,engine_volume text,fuel text,power text,drive text,side text,position text,source_id uuid,is_conflict boolean not null default false,confirmed boolean not null default false,notes text,created_at timestamptz not null default now());
create table if not exists public.sources(id uuid primary key default gen_random_uuid(),product_id uuid references public.products(id) on delete cascade,source_type text not null,source_name text not null,source_url text,checked_at timestamptz not null default now(),confidence_score integer check(confidence_score between 0 and 100),raw_data jsonb not null default '{}'::jsonb);
create table if not exists public.research_runs(id uuid primary key default gen_random_uuid(),product_id uuid references public.products(id) on delete cascade,seller_article text not null,use_riv boolean not null default false,status text not null default 'PENDING',progress jsonb not null default '{}'::jsonb,aggregated_data jsonb not null default '{}'::jsonb,conflicts jsonb not null default '[]'::jsonb,warnings jsonb not null default '[]'::jsonb,ai_result jsonb not null default '{}'::jsonb,confidence_score integer check(confidence_score between 0 and 100),started_at timestamptz,finished_at timestamptz,created_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table if not exists public.product_images(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,source text not null default 'OZON',url text not null,sort_order integer not null default 0,is_main boolean not null default false,storage_path text,created_at timestamptz not null default now());
create table if not exists public.jobs(id uuid primary key default gen_random_uuid(),store_id uuid references public.stores(id) on delete cascade,product_id uuid references public.products(id) on delete cascade,job_type text not null,payload jsonb not null default '{}'::jsonb,status text not null default 'PENDING',progress integer not null default 0,attempt_count integer not null default 0,last_error text,result jsonb not null default '{}'::jsonb,started_at timestamptz,finished_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),store_id uuid references public.stores(id) on delete cascade,product_id uuid references public.products(id) on delete cascade,user_id uuid references public.profiles(id),action text not null,before_data jsonb not null default '{}'::jsonb,after_data jsonb not null default '{}'::jsonb,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.analytics_daily(id uuid primary key default gen_random_uuid(),store_id uuid not null references public.stores(id) on delete cascade,product_id uuid references public.products(id) on delete cascade,day date not null,ordered_units numeric not null default 0,revenue numeric not null default 0,cancellations numeric not null default 0,views numeric not null default 0,clicks numeric not null default 0,conversion numeric not null default 0,raw jsonb not null default '{}'::jsonb,unique(store_id,product_id,day));
create table if not exists public.prompt_templates(id uuid primary key default gen_random_uuid(),store_id uuid references public.stores(id) on delete cascade,key text not null,system_prompt text not null,version integer not null default 1,active boolean not null default true,created_at timestamptz not null default now(),unique(store_id,key,version));
create or replace function public.is_store_member(target_store uuid) returns boolean language sql stable security invoker set search_path = public, pg_temp as $select exists(select 1 from public.store_memberships sm where sm.store_id=target_store and sm.user_id=(select auth.uid()))$;
create or replace function public.is_store_admin(target_store uuid) returns boolean language sql stable security invoker set search_path = public, pg_temp as $select exists(select 1 from public.store_memberships sm where sm.store_id=target_store and sm.user_id=(select auth.uid()) and sm.role='ADMIN')$;
alter table public.profiles enable row level security;
alter table public.stores enable row level security;
alter table public.store_memberships enable row level security;
alter table public.products enable row level security;
alter table public.product_drafts enable row level security;
alter table public.part_numbers enable row level security;
alter table public.vehicle_applications enable row level security;
alter table public.sources enable row level security;
alter table public.research_runs enable row level security;
alter table public.product_images enable row level security;
alter table public.jobs enable row level security;
alter table public.audit_logs enable row level security;
alter table public.analytics_daily enable row level security;
alter table public.prompt_templates enable row level security;
grant select,insert,update,delete on all tables in schema public to authenticated;

create policy profiles_self on public.profiles for select to authenticated using(id=auth.uid());
create policy stores_member on public.stores for select to authenticated using(public.is_store_member(id));
create policy membership_self on public.store_memberships for select to authenticated using(user_id=(select auth.uid()));
create policy products_member_select on public.products for select to authenticated using(public.is_store_member(store_id));
create policy products_member_insert on public.products for insert to authenticated with check(public.is_store_member(store_id));
create policy products_member_update on public.products for update to authenticated using(public.is_store_member(store_id)) with check(public.is_store_member(store_id));
create policy drafts_member on public.product_drafts for all to authenticated using(exists(select 1 from public.products p where p.id=product_id and public.is_store_member(p.store_id))) with check(exists(select 1 from public.products p where p.id=product_id and public.is_store_member(p.store_id)));
create policy parts_member on public.part_numbers for all to authenticated using(exists(select 1 from public.products p where p.id=product_id and public.is_store_member(p.store_id))) with check(exists(select 1 from public.products p where p.id=product_id and public.is_store_member(p.store_id)));
create policy vehicles_member on public.vehicle_applications for all to authenticated using(exists(select 1 from public.products p where p.id=product_id and public.is_store_member(p.store_id))) with check(exists(select 1 from public.products p where p.id=product_id and public.is_store_member(p.store_id)));
create policy sources_member on public.sources for all to authenticated using(product_id is null or exists(select 1 from public.products p where p.id=product_id and public.is_store_member(p.store_id))) with check(product_id is null or exists(select 1 from public.products p where p.id=product_id and public.is_store_member(p.store_id)));
create policy research_member on public.research_runs for all to authenticated using(product_id is null or exists(select 1 from public.products p where p.id=product_id and public.is_store_member(p.store_id))) with check(product_id is null or exists(select 1 from public.products p where p.id=product_id and public.is_store_member(p.store_id)));
create policy images_member on public.product_images for all to authenticated using(exists(select 1 from public.products p where p.id=product_id and public.is_store_member(p.store_id))) with check(exists(select 1 from public.products p where p.id=product_id and public.is_store_member(p.store_id)));
create policy jobs_member on public.jobs for all to authenticated using(store_id is null or public.is_store_member(store_id)) with check(store_id is null or public.is_store_member(store_id));
create policy audit_member on public.audit_logs for select to authenticated using(store_id is null or public.is_store_member(store_id));
create policy analytics_member on public.analytics_daily for select to authenticated using(public.is_store_member(store_id));
create policy prompts_member on public.prompt_templates for all to authenticated using(store_id is null or public.is_store_member(store_id)) with check(store_id is null or public.is_store_member(store_id));
